"""End-to-end verification with independently computed expectations.

Everything asserted here is derived without calling the binding
implementation:

* expected filter/aggregate results are computed in plain Python from the
  literal source rows;
* an independent DuckDB SQL string (hand-written, not generated by Ibis)
  is run directly against replacement scans to cross-check the values;
* a same-named *catalog* table holding deliberately different numbers is
  created first and re-read after every binding call to prove the user
  table and its contents survive.

Run::

    .venv/bin/python -I examples/relation_bindings/verification.py
"""

from __future__ import annotations

import duckdb
import pyarrow as pa

import ibis

# -- source batches: small enough to verify every number by hand --------
BATCH_A = pa.table(
    {
        "id": [1, 2, 3, 4],
        "group": ["x", "y", "x", "y"],
        "v": [10, 20, 30, 40],
    }
)
BATCH_B = pa.table(
    {
        "id": [5, 6],
        "group": ["x", "z"],
        "v": [50, 60],
    }
)

# hand-computed expectations
EXPECT_A_FILTER = [10, 30]                       # v where group == 'x'
EXPECT_B_FILTER = [50]
EXPECT_A_GROUPS = {"x": 40, "y": 60}            # sum(v) by group
EXPECT_B_GROUPS = {"x": 50, "z": 60}
# catalog table values are intentionally far away from the batch values
CATALOG_ROWS = [(-1, "x", -999), (-2, "z", -998)]


def check(condition: bool, message: str) -> None:
    if not condition:
        raise AssertionError(message)
    print(f"  ok: {message}")


def main() -> None:
    raw = duckdb.connect()
    raw.execute("CREATE TABLE t (id BIGINT, \"group\" VARCHAR, v BIGINT)")
    raw.executemany("INSERT INTO t VALUES (?, ?, ?)", CATALOG_ROWS)

    con = ibis.duckdb.connect()
    con.con.execute(
        "CREATE TABLE t (id BIGINT, \"group\" VARCHAR, v BIGINT)"
    )
    con.con.executemany(
        "INSERT INTO t VALUES (?, ?, ?)", CATALOG_ROWS
    )

    t = ibis.table(
        dict(id="int64", group="string", v="int64"), name="t"
    )
    filtered = t.filter(t.group == "x").select(t.v).order_by(t.v)
    grouped = (
        t.group_by("group")
        .aggregate(total=t.v.sum())
        .order_by("group")
    )

    # ------------------------------------------------------------------
    # 1. alternate batches on the very same expression graph
    # ------------------------------------------------------------------
    print("alternating batches:")
    a = con.execute(filtered, table_bindings={t: BATCH_A}).v.tolist()
    b = con.execute(filtered, table_bindings={t: BATCH_B}).v.tolist()
    check(a == EXPECT_A_FILTER, f"batch A filter -> {a}")
    check(b == EXPECT_B_FILTER, f"batch B filter -> {b}")

    ga = dict(
        con.execute(grouped, table_bindings={t: BATCH_A}).values
    )
    gb = dict(
        con.execute(grouped, table_bindings={t: BATCH_B}).values
    )
    check(ga == EXPECT_A_GROUPS, f"batch A groups -> {ga}")
    check(gb == EXPECT_B_GROUPS, f"batch B groups -> {gb}")

    # expression graph is still the unbound original
    check(
        type(t.op()).__name__ == "UnboundTable",
        "graph remains unbound after repeated execution",
    )

    # ------------------------------------------------------------------
    # 2. same-named catalog table is never read or modified
    # ------------------------------------------------------------------
    print("catalog table protection:")
    surviving = con.con.execute(
        "SELECT id, \"group\", v FROM t ORDER BY id"
    ).fetchall()
    check(
        sorted(surviving) == sorted(CATALOG_ROWS),
        f"catalog rows intact -> {surviving}",
    )

    # unbound execution without a binding still reads the catalog table
    db_only = con.con.execute(
        'SELECT v FROM t WHERE "group" = \'x\''
    ).fetchall()
    check(
        db_only == [(-999,)],
        "without bindings the catalog table is what gets read",
    )

    # ------------------------------------------------------------------
    # 3. independent SQL cross-check (hand-written, no ibis generation)
    # ------------------------------------------------------------------
    print("independent SQL cross-check:")
    sql = (
        'SELECT v FROM t WHERE "group" = ? ORDER BY v'
    )
    raw.register("t", BATCH_A)
    sql_a = [row[0] for row in raw.execute(sql, ["x"]).fetchall()]
    raw.unregister("t")
    raw.register("t", BATCH_B)
    sql_b = [row[0] for row in raw.execute(sql, ["x"]).fetchall()]
    raw.unregister("t")
    check(sql_a == a == EXPECT_A_FILTER, "SQL matches batch A and ibis")
    check(sql_b == b == EXPECT_B_FILTER, "SQL matches batch B and ibis")

    raw_catalog = raw.execute(
        'SELECT v FROM t WHERE "group" = \'x\''
    ).fetchall()
    check(raw_catalog == [(-999,)], "raw catalog table also intact")
    raw.close()
    con.disconnect()
    print("\nALL VERIFICATIONS PASSED")


if __name__ == "__main__":
    main()
